import{_ as a,o,c as r,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Réplicas e failover","description":"","frontmatter":{},"headers":[],"relativePath":"pt-BR/guide/replicas.md","filePath":"pt-BR/guide/replicas.md"}'),s={name:"pt-BR/guide/replicas.md"};function t(d,e,n,c,p,m){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="replicas-e-failover" tabindex="-1">Réplicas e failover <a class="header-anchor" href="#replicas-e-failover" aria-label="Permalink to &quot;Réplicas e failover&quot;">​</a></h1><p>Um banco PostgreSQL no CloudNativePG pode rodar de 1 a 3 instâncias, cada uma num servidor diferente, em <strong>Instâncias e replicação</strong> na sua página. Mais instâncias precisam de mais <a href="./servers">servidores</a>.</p><div class="warning custom-block"><p class="custom-block-title">Isto não é alta disponibilidade</p><p>A menos que você <a href="./servers#control-plane">rode o plano de controle do cluster em três servidores</a>, ele roda só no servidor principal, e se o principal for perdido nenhum failover acontece. Veja <a href="./limits#control-plane">O que o Orbit não promete</a>.</p></div><h2 id="preview" tabindex="-1">A prévia <a class="header-anchor" href="#preview" aria-label="Permalink to &quot;A prévia {#preview}&quot;">​</a></h2><p>Ela escolhe um servidor para cada instância, começando pelo do primário, e recusa:</p><ul><li>quando não há servidores suficientes com espaço para a memória do banco;</li><li>replicação síncrona com duas instâncias, porque perder qualquer um dos servidores pararia todas as escritas.</li></ul><h2 id="replication" tabindex="-1">Replicação <a class="header-anchor" href="#replication" aria-label="Permalink to &quot;Replicação {#replication}&quot;">​</a></h2><ul><li><strong>Assíncrona</strong> (o padrão): os commits não esperam as réplicas, então um failover pode perder as últimas escritas.</li><li><strong>Síncrona</strong> (três instâncias): cada commit espera até uma réplica tê-lo, e só é promovida uma réplica que tem todas as escritas confirmadas, então um failover não perde nenhuma. As escritas ficam mais lentas e param se dois dos três servidores forem perdidos.</li></ul><h2 id="failover" tabindex="-1">Failover <a class="header-anchor" href="#failover" aria-label="Permalink to &quot;Failover {#failover}&quot;">​</a></h2><p>Quando o servidor do primário é perdido, uma réplica é promovida e o endereço do banco passa a apontar para o novo primário, então as aplicações mantêm as suas variáveis. Quando aquele servidor volta, a instância dele entra de novo como réplica.</p><p>Um primário que perde a rede mas continua rodando não alcança nem o cluster nem as réplicas, então ele se reinicia e encerra as sessões cerca de meio minuto depois do corte. Isso acontece antes de uma réplica ser promovida, então só um primário aceita escritas de cada vez.</p><p><strong>Tornar primário</strong> numa réplica a promove de propósito (um switchover). Levou de 9 a 10 segundos num cluster de teste.</p><h2 id="shows" tabindex="-1">O que o Orbit mostra <a class="header-anchor" href="#shows" aria-label="Permalink to &quot;O que o Orbit mostra {#shows}&quot;">​</a></h2><p>A página lista cada instância com o seu servidor, o seu papel e o quanto uma réplica está atrasada. Todo failover e switchover fica registrado na atividade e na linha do tempo do banco com o que o Orbit mediu:</p><ul><li><strong>Quanto tempo o banco ficou sem primário:</strong> do momento em que o antigo funcionou pela última vez (o último sinal do seu servidor ou o último commit replicado) até a promoção.</li><li><strong>O que foi mantido:</strong> com replicação síncrona, toda escrita confirmada. Com assíncrona, o horário da escrita mais nova que o novo primário tem; o que o primário antigo confirmou depois disso se perdeu.</li></ul><p>Backups e a recuperação até um momento continuam funcionando depois de um failover, já que o arquivo segue o primário.</p><h2 id="tested" tabindex="-1">Testado sob falhas <a class="header-anchor" href="#tested" aria-label="Permalink to &quot;Testado sob falhas {#tested}&quot;">​</a></h2><p>O teste de aceitação do Orbit quebra de propósito um cluster de três nós: o servidor principal e mais dois, rodando como contêineres numa máquina só. Dois bancos PostgreSQL 17 rodam ali com três instâncias cada, uma por servidor. Um replica de forma assíncrona; o outro, de forma síncrona, e arquiva o WAL num armazenamento compatível com S3. Uma aplicação escreve em cada um pelo endereço do banco cinco vezes por segundo e registra quais escritas foram confirmadas.</p><table tabindex="0"><thead><tr><th>Cenário</th><th>Medido</th></tr></thead><tbody><tr><td>O servidor do primário para</td><td>63 a 64 s sem primário; escritas de volta depois de 67 a 70 s. Nenhuma escrita confirmada perdida, assíncrona ou síncrona.</td></tr><tr><td>O servidor do primário perde a rede</td><td>96 s sem primário; escritas de volta depois de 101 a 103 s. O primário assíncrono isolado parou de aceitar escritas 34 s depois do corte, 61 s antes da promoção, e as escritas que ele aceitou nesses 34 s se perderam. O síncrono não aceitou nenhuma. Nunca houve dois primários aceitando escritas.</td></tr><tr><td>Uma mudança destrutiva (<code>delete</code> sem <code>where</code>)</td><td><a href="./backups#point-in-time">Restaurado</a> para o segundo anterior em 63 s.</td></tr><tr><td>Todas as instâncias e volumes perdidos</td><td><a href="./backups#rebuild">Reconstruído só a partir do arquivo</a>: escritas de volta 51 s depois da perda. Os 41 s de escritas que não tinham chegado ao arquivo se perderam, e o Orbit informou exatamente até qual commit recuperou.</td></tr><tr><td>Uma configuração que não sobrevive à perda de um servidor</td><td>A prévia recusa.</td></tr></tbody></table><p>Os failovers foram medidos de novo em três servidores separados, com replicação síncrona, como parte de <a href="./availability#real">perder um servidor</a>: um novo primário depois de 1 minuto e 44 a 45 segundos e nenhuma escrita confirmada perdida.</p><p>O que continua em aberto está em <a href="./limits#databases">O que o Orbit não promete</a>.</p>',21)])])}const v=a(s,[["render",t]]);export{u as __pageData,v as default};
